"""Migration of the Meridian CRM 4.2 order_fulfilment workflow."""

from decimal import Decimal
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply the legacy empty-value numeric coercion."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup_credit_hold(record: dict, tables: dict) -> Any:
    """Return CRED_HOLD from the first matching live ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first eligible transition in legacy document order."""
    record_copy = dict(record)

    # E -> A: approve
    if (
        state == "E"
        and event == "approve"
        and _numeric(record.get("TOT_AMT", "")) > 0
    ):
        return {
            "state": "A",
            "record": record_copy,
            "audits": ["ORD_APPR"],
            "notifies": [],
            "matched": True,
        }

    # A -> S: ship
    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": record_copy,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    # S -> I: invoice
    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": record_copy,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    # E -> X: cancel
    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    # A -> X: cancel unless the first matching live account is on credit hold.
    if (
        state == "A"
        and event == "cancel"
        and _lookup_credit_hold(record, tables) != "Y"
    ):
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    # I -> X: cancel invoiced order
    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
